import type { SlotApiEntryResponse, SlotApiSpinResponse, SlotApiStepObject } from '../net/SlotApiTypes';
import { SLOT_API_CODE, SlotApiHttpError } from '../net/SlotApiTypes';
import {
    currencyScale,
    toBetPlan,
    toLegacyBetDetail,
    toLegacyBetHistory,
    toLegacyFreeSpin,
    toLegacyJackpotSnapshot,
    toLegacySlotInitDataFromEntry,
    toLegacySpinResponse,
    type SlotBetOption,
    type SlotFreeSpin,
    type SlotSpinContext
} from '../net/SlotResponseAdapter';
import { switchLanguage } from '../i18n/i18nHelper';
import { getLocalizedString } from '../i18n/LanguageData';
import type { BetHistoryDetail } from '../models/BetHistory';
import type { SlotGridLayout } from '../models/SlotGrid';
import {
    GetBetDetailResponseHandler,
    GetBetHistoryResponseHandler,
    GetGameInfoResponseHandler,
    GetGameStateResponseHandler,
    JackpotPoolResponseHandler,
    SlotSpinResponseHandler
} from '../net/SlotApiHandlers';
import { SLOT_API_RESPONSE_TYPE } from '../net/SlotApiTypes';
import { SlotApiClient } from '../net/SlotApiClient';
import { autoFallbackToMock, isMock } from '../config/GameConfig';
import { startGameMock } from '../net/mocks/start';
import { GAMESTOREMAP } from './StoreMap';
import GameConfigManager from '../config/GameConfigManager';
import { API_GAME_ID } from '../config/GameConst';

const DEFAULT_SLOT_API_CONNECTION = {
    httpBaseUrl: 'https://gp-play.ggap.elitepro.ltd',
    wsUrl: 'wss://gp-play.ggap.elitepro.ltd/ws'
} as const;

/**
 * 玩家端 API 位址：所有平台（網頁、原生）都只用這個常數，不讀 config.json。
 * （Entry 的 config.json 是原生才有、網頁沒有，且內容還是舊後端，位址會因平台不同）
 */
function getSlotApiConnection(): { httpBaseUrl: string; wsUrl: string } {
    return { httpBaseUrl: DEFAULT_SLOT_API_CONNECTION.httpBaseUrl, wsUrl: DEFAULT_SLOT_API_CONNECTION.wsUrl };
}
/** 獎池輪詢間隔：玩家端沒有推播，GET /player/jackpots 每分鐘最多 30 次，保守取 30 秒 */
const JACKPOT_POLL_MS = 30000;
/** 注單列表每頁筆數（原本一次抓 20 筆） */
const HISTORY_PAGE_SIZE = 20;

/** 一局最多接著打幾步，防止無窮迴圈（slot-integration.md §5.2） */
const MAX_ROUND_STEPS = 500;

export default class HttpClientStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/HttpClientStore') */
    public readonly $modelType = 'store/HttpClientStore';

    private _userID = '';
    get userID(): string {
        return this._userID;
    }
    setUserID(value: string): void {
        this._userID = value;
    }

    private _signature = '';
    get signature(): string {
        return this._signature;
    }
    setSignature(value: string): void {
        this._signature = value;
    }

    private _authKey = '';
    get authKey(): string {
        return this._authKey;
    }
    setAuthKey(value: string): void {
        this._authKey = value;
    }

    private _isUpdate = true;
    get isUpdate(): boolean {
        return this._isUpdate;
    }
    setIsUpdate(value: boolean): void {
        this._isUpdate = value;
    }

    storeManager: any;
    debugControl: object | null = null;
    serviceURL: string | null = null;
    cashierURL: string | null = null;
    lobbyURL: string | null = null;
    private data: any = null;
    private currency: string = 'TWD';
    private mockMode: boolean = isMock();
    /** 玩家端 API 的進場資料（entry）；mock 模式為 null */
    private entry: SlotApiEntryResponse | null = null;
    /** 攤平後的下注清單（金額 ↔ bet_size／bet_level），下注時用金額反查 */
    private betPlan: SlotBetOption[] = [];
    /** 下一次 bet 的 prev_step_id：上一步的 step_id；沒玩過是空字串（它同時是冪等鍵，不要自己產生） */
    private prevStepId = '';
    /** 最近一次拿到的步驟：免費遊戲下一轉用它的 step_id 與 bet_size／bet_level 續打 */
    private lastStep: SlotApiStepObject | null = null;
    /** 這一局開局時選的下注額，轉換免費遊戲每一轉的顯示金額用 */
    private spinOption: SlotBetOption | null = null;
    /** 免費遊戲前面各轉累積的倍數（MULTIPLIER_APPLIED 的 acc_after） */
    private freeAccumulated = 0;
    private jackpotTimer: ReturnType<typeof setInterval> | null = null;

    private mockSwitch: Promise<SlotApiClient> | null = null;
    private readonly cache = {
        betDetails: new Map<string, BetHistoryDetail>()
    };
    private slotApiClient: SlotApiClient | null = null;
    private slotApiLoginPromise: Promise<void> | null = null;

    /** 保留建構子參數是為了相容 GameConfigManager 裡 `new HttpClientStore({})` 的舊呼叫方式 */
    constructor(_props?: unknown) {}

    setManager(manager: any): void {
        this.storeManager = manager;
    }

    /** 取得初始資料並同步各 Store */
    async gameInitial(): Promise<void> {
        try {
            try {
                await this.initializeGame();
            } catch (error) {
                // 真實／mock 只在進場時決定一次（連不上才切 mock），進場成功後整個連線期間固定，不會中途切換
                if (!this.canFallbackToMock(error)) throw error;
                await this.fallbackToMock(error);
                await this.initializeGame();
            }
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 真實與 mock 共用初始化適配及 Store 更新，不建立第二套畫面流程。 */
    private async initializeGame(): Promise<void> {
        // 沒有 token：開發版走 mock；正式版不切換，交給 enter() 報缺少 token
        if (!this.mockMode && !GameConfigManager.token && autoFallbackToMock()) {
            await this.fallbackToMock();
        }
        this.currency = this.resolveCurrency();
        console.log('HttpClientStore.gameInitial currency:', this.currency);

        const gameStore = this.storeManager.getGameStore();
        if (this.mockMode) {
            // 舊協定（WebSocket 三支請求）：只有 mock 還走這條
            await this.fetchInitialGameData();
            const { toLegacySlotInitData } = await import('../net/SlotResponseAdapter');
            this.data = toLegacySlotInitData(gameStore.gameInfoData, gameStore.gameStateData, gameStore.slotLayout);
            console.log('HttpClientStore.gameInitial info:', gameStore.gameInfoData);
            console.log('HttpClientStore.gameInitial state:', gameStore.gameStateData);
        } else {
            // 玩家端 API v5.1：進場一次拿齊限紅、檔位與餘額
            this.data = await this.enter(gameStore.slotLayout);
        }

        this.currency = this.data.game.currency || this.currency;
        this.setAuthKey(this.data.game.auth_key);

        gameStore.setInitExtra(this.data.machine_info.extra);
        gameStore.setGameInitData(this.data);

        const userStore = this.storeManager.getUserStore();
        userStore.setBalance(Number(this.data.game.balance) || 0);

        const templateStore = this.storeManager.getModel('TemplateStore');
        const machineInfo = this.data.machine_info;
        templateStore.setBetLeavel(machineInfo.bet_level);

        // last_bet 存在才用
        const lastBet = Number(machineInfo.last_bet);
        const betLevels = machineInfo.bet_level.map((bet: number) => Number(bet));
        const defaultBet = betLevels.includes(lastBet) ? lastBet : (betLevels[0] ?? 0);
        templateStore.setBetBalance(defaultBet);
        const index = betLevels.findIndex((bet: number) => bet === defaultBet);
        templateStore.setBetIndex(index >= 0 ? index : 0);
    }

    /**
     * 玩家端 API 進場（slot-integration.md §5.1）：用大廳給的 token 打 entry，
     * 回傳舊 UI 使用的初始化資料。
     * @throws 缺少 token，或 entry 失敗（SlotApiHttpError）
     */
    private async enter(layout: SlotGridLayout): Promise<any> {
        const token = GameConfigManager.token;
        console.log('[HttpClientStore] enter', { hasToken: !!token, baseUrl: getSlotApiConnection().httpBaseUrl });
        if (!token) throw new Error('missing token：網址需帶 ?t=，或由 Entry 放進 launchContext.token');
        const client = await this.getClient();
        client.setToken(token);

        const entry = await client.entry(API_GAME_ID);
        console.log(`[HttpClientStore] entry next_step=${entry.next_step}`, entry);
        await this.applyLanguage(entry.language);
        this.applyEntry(entry);
        return toLegacySlotInitDataFromEntry(entry, this.betPlan, layout);
    }

    /** 記下進場資料：限紅清單與下一個 prev_step_id。進場與重新進場共用 */
    private applyEntry(entry: SlotApiEntryResponse): void {
        this.entry = entry;
        this.betPlan = toBetPlan(entry);
        this.prevStepId = entry.last_step?.step_id ?? '';
        // 續打（RESUME_ROUND）、等待、客服等分支還沒接，先只記錄
        if (entry.next_step !== 'PLAY') console.warn(`[HttpClientStore] next_step=${entry.next_step} 尚未處理`);
    }

    private reentering: Promise<void> | null = null;

    /**
     * HTTP 401（session 失效）：重打一次 entry 接回 session 與最新的 last_step（slot-integration.md §4.3）。
     * 不自動重送原本的請求，由玩家再操作一次；entry 回 4011 等錯誤時照一般錯誤顯示。同時多個 401 只重進一次。
     */
    private reenter(): Promise<void> {
        this.reentering ??= (async () => {
            try {
                const client = await this.getClient();
                const entry = await client.entry(API_GAME_ID);
                this.applyEntry(entry);
                this.storeManager.getUserStore().setBalance(Number(entry.player.balance) || 0);
            } catch (error) {
                this.handleError(error);
            } finally {
                this.reentering = null;
            }
        })();
        return this.reentering;
    }

    /** 建立盤面設定 */
    async gameConfig(): Promise<void> {
        try {
            const { toLegacySlotConfigData } = await import('../net/SlotResponseAdapter');
            if (!this.mockMode) {
                const gameStore = this.storeManager.getGameStore();
                // 買入倍率取 entry 的 buy_options；EoH 只有 buy100，倍率就是 buy_super 用的值
                const buy = this.entry?.game.buy_options[0];
                gameStore.setConfigData(toLegacySlotConfigData(null, gameStore.slotLayout, buy ? Number(buy.multiple) : undefined));
                return;
            }
            const gameStore = this.storeManager.getGameStore();
            if (!gameStore.gameInfoData) {
                await (await this.getClient()).getGameInfo(GameConfigManager.launchContext.gameCode, this.currency);
            }
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 發送 Spin對應 Handler 寫入 GameStore */
    async spin(bet: number | string, buyFeatureType?: unknown): Promise<SlotApiSpinResponse | null> {
        try {
            const client = await this.getClient();
            if (this.mockMode) {
                // 舊協定（WebSocket）：只有 mock 還走這條
                return await client.spin(GameConfigManager.launchContext.gameCode, String(bet), !!buyFeatureType);
            }
            // 玩家端 API v5.1：用下注額反查 bet_size／bet_level，開新局並取得這一轉（開局步與其後的連消步），
            // 轉成演出使用的資料交給 Handler。進免費遊戲後，每一轉在播放時才由 nextFreeSpin() 向後端要
            const option = this.betPlan.find((item) => Number(item.amount) === Number(bet));
            if (!option || !this.entry) throw new Error(`下注額 ${bet} 不在限紅清單，或尚未進場`);
            const steps = await this.playSpin(option, !!buyFeatureType);
            const response = toLegacySpinResponse(steps, this.spinContext(option));
            client.dispatch(SLOT_API_RESPONSE_TYPE.SLOT_SPIN_RESPONSE, response);
            return response;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }

    /**
     * 開新局並取得這一轉（slot-integration.md §5.2）：第一步用 prev_step_id 開新局並扣款，
     * 同一轉還有連消（next_step_type 為 TUMBLE）就用上一步的 step_id 接著打（不扣款）。
     * 局還沒結束（免費遊戲接著開始）時停在這裡，之後每一轉由 nextFreeSpin() 在播放時才要。
     * @param buy true 時買入免費遊戲（EoH 只有一檔 buy100）
     * @returns 這一轉依序的所有步驟
     */
    private async playSpin(option: SlotBetOption, buy: boolean): Promise<SlotApiStepObject[]> {
        const client = await this.getClient();
        const buyTier = this.entry?.game.buy_options[0]?.tier_id;
        if (buy && !buyTier) throw new Error('這款遊戲目前不開放買入（buy_options 為空）');
        const open = (prevStepId: string) =>
            client.bet({
                prev_step_id: prevStepId,
                bet_size: option.size,
                bet_level: option.level,
                spin_type: buy ? 'BUY_FEATURE' : 'BASE',
                ...(buy ? { buy_tier: buyTier } : {})
            });

        let first: SlotApiStepObject;
        try {
            first = await open(this.prevStepId);
        } catch (error) {
            // 4023：prev_step_id 不是最新一步（另一個分頁或裝置打過），換成 latest_step_id 重打一次
            if (!(error instanceof SlotApiHttpError) || error.code !== SLOT_API_CODE.STALE_STEP || !error.latestStepId) throw error;
            first = await open(error.latestStepId);
        }
        this.spinOption = option;
        this.freeAccumulated = 0;
        this.recordStep(first);
        return this.drainSpin(first, option);
    }

    /**
     * 免費遊戲的下一轉：用上一步的 step_id 向後端要這一轉（FREE_SPIN 步與其後的連消步，不扣款，§5.2）。
     * 演出播完一轉才呼叫，不預先把整局取完（文件：播完再要下一步）。
     * @returns 這一轉轉成舊格式的步驟、倍數資訊與剩餘轉數；失敗時顯示錯誤並回 null
     */
    async nextFreeSpin(): Promise<SlotFreeSpin | null> {
        try {
            const previous = this.lastStep;
            if (!previous?.next_step_type || !this.spinOption) throw new Error('沒有可以續打的免費遊戲');
            const first = await (await this.getClient()).bet({
                prev_step_id: previous.step_id,
                bet_size: previous.bet_size,
                bet_level: previous.bet_level
            });
            this.recordStep(first);
            const steps = await this.drainSpin(first, this.spinOption);
            const spin = toLegacyFreeSpin(steps, this.spinContext(this.spinOption), this.freeAccumulated);
            this.freeAccumulated = spin.multiplier.acc;
            return spin;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }

    /**
     * 從 first 接著打，直到這一轉結束：連消步（TUMBLE、FREE_TUMBLE）屬於同一轉，其他非 null 的 next_step_type
     * （下一轉 FREE_SPIN 等）或 null（局結束）都停在這裡。續打要帶本局的 bet_size／bet_level，不帶模式欄。
     * @param fallback 步驟物件沒帶 bet_size／bet_level 時（舊局）用的值
     * @returns 含 first 在內的這一轉所有步驟
     */
    private async drainSpin(first: SlotApiStepObject, fallback: SlotBetOption | null): Promise<SlotApiStepObject[]> {
        const client = await this.getClient();
        const steps = [first];
        let step = first;
        while (step.next_step_type === 'TUMBLE' || step.next_step_type === 'FREE_TUMBLE') {
            if (steps.length >= MAX_ROUND_STEPS) throw new Error(`一轉超過 ${MAX_ROUND_STEPS} 步，停止`);
            step = await client.bet({
                prev_step_id: step.step_id,
                bet_size: step.bet_size || fallback?.size || '',
                bet_level: step.bet_level || fallback?.level || 0
            });
            this.recordStep(step);
            steps.push(step);
        }
        if (step.next_step_type === 'SELECT') throw new Error('局在等選擇（SELECT），1001 沒有選玩法');
        return steps;
    }

    /** 記下最新一步：下一個 bet 的 prev_step_id，以及免費遊戲續打要用的 step_id 與下注額 */
    private recordStep(step: SlotApiStepObject): void {
        this.prevStepId = step.step_id;
        this.lastStep = step;
    }

    /** 轉換 spin 資料需要的下注與版面資訊 */
    private spinContext(option: SlotBetOption): SlotSpinContext {
        return {
            baseBet: option.amount,
            minScale: this.entry ? currencyScale(this.entry) : 2,
            currency: this.entry?.player.currency ?? this.currency,
            visibleRows: this.storeManager.getGameStore().slotLayout.visibleRows
        };
    }

    /** 取得歷史列表 對應 Handler 寫入 Store */
    async getHistory(): Promise<any> {
        if (!this.isUpdate) {
            return this.storeManager.getGameStore().historyData;
        }

        try {
            const client = await this.getClient();
            if (this.mockMode) {
                // 舊協定（WebSocket）：只有 mock 還走這條
                await client.getBetHistory(GameConfigManager.launchContext.gameCode, 20);
            } else {
                // 玩家端 API v5.1：頁碼列表，轉成舊格式交給既有 Handler
                const list = await client.historyList(API_GAME_ID, 1, HISTORY_PAGE_SIZE);
                client.dispatch(SLOT_API_RESPONSE_TYPE.GET_BET_HISTORY_RESPONSE, toLegacyBetHistory(list));
            }
            return this.storeManager.getGameStore().historyData;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }

    /** 訂閱 Jackpot：玩家端 API 沒有推播，改成定時輪詢 GET /player/jackpots（mock 仍走舊的 WS 訂閱） */
    async subscribeJackpotPool(): Promise<void> {
        try {
            if (this.mockMode) {
                await (await this.getClient()).subscribeJackpotPool(GameConfigManager.launchContext.gameCode);
                return;
            }
            // 進場資料更新時會呼叫多次訂閱，已經在輪詢就不重複查
            if (this.jackpotTimer) return;
            this.jackpotTimer = setInterval(() => void this.pollJackpotPool(), JACKPOT_POLL_MS);
            await this.pollJackpotPool();
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 取消訂閱 Jackpot */
    async unsubscribeJackpotPool(): Promise<void> {
        if (!this.mockMode) {
            this.stopJackpotPolling();
            return;
        }
        try {
            await (await this.getClient()).unsubscribeJackpotPool(GameConfigManager.launchContext.gameCode);
        } catch (error) {
            this.handleError(error);
        }
    }

    /** 查一次獎池水位並更新畫面；輪詢中失敗只記錄，不彈提示（401 仍要重打 entry） */
    private async pollJackpotPool(): Promise<void> {
        try {
            const client = await this.getClient();
            if (this.mockMode) {
                await client.subscribeJackpotPool(GameConfigManager.launchContext.gameCode);
                return;
            }
            const response = await client.jackpots(API_GAME_ID);
            const currency = this.entry?.player.currency ?? this.currency;
            client.dispatch(SLOT_API_RESPONSE_TYPE.GET_JACKPOT_POOL_RESPONSE, toLegacyJackpotSnapshot(response, API_GAME_ID, currency));
        } catch (error) {
            console.warn('[HttpClientStore] 獎池查詢失敗', error);
            if (error instanceof SlotApiHttpError && error.kind === 'unauthorized') void this.reenter();
        }
    }

    private stopJackpotPolling(): void {
        if (this.jackpotTimer) clearInterval(this.jackpotTimer);
        this.jackpotTimer = null;
    }

    /** 有序關閉 先取消訂閱再關 WebSocket */
    async shutdown(): Promise<void> {
        try {
            if (this.slotApiClient) {
                await this.unsubscribeJackpotPool();
            }
        } catch {
            // 取消訂閱失敗不阻擋關閉
        }
        this.close();
    }

    /** 關閉 WS heartbeat 與自動重連 */
    close(): void {
        this.stopJackpotPolling();
        this.slotApiClient?.close();
        this.slotApiClient = null;
        this.slotApiLoginPromise = null;
    }

    /** 取得單筆歷史明細 使用記憶體快取 */
    async getHistoryDetail(roundId: string): Promise<BetHistoryDetail | null> {
        const cachedDetail = this.getCachedBetDetail(roundId);
        if (cachedDetail) return cachedDetail;

        try {
            const client = await this.getClient();
            if (this.mockMode) {
                // 舊協定（WebSocket）：只有 mock 還走這條
                await client.getBetDetail(roundId);
            } else {
                // 玩家端 API v5.1：單局重播，轉成舊格式交給既有 Handler 快取
                const response = await client.historyRound(roundId);
                const buyMultiple = Number(this.entry?.game.buy_options[0]?.multiple ?? 0);
                const visibleRows = this.storeManager.getGameStore().slotLayout.visibleRows;
                client.dispatch(SLOT_API_RESPONSE_TYPE.GET_BET_DETAIL_RESPONSE, toLegacyBetDetail(response, visibleRows, buyMultiple));
            }
            return this.getCachedBetDetail(roundId) ?? null;
        } catch (error) {
            this.handleError(error);
            return null;
        }
    }

    /** 取得歷史明細 */
    private getCachedBetDetail(roundId: string): BetHistoryDetail | undefined {
        return this.cache.betDetails.get(roundId);
    }

    /** mock 沿用既有初始化請求與 Handler；錯誤交由共用入口處理。 */
    private async fetchInitialGameData(): Promise<void> {
        const { gameCode } = GameConfigManager.launchContext;
        const client = await this.getClient();
        await client.getGameInfo(gameCode, this.currency);
        await client.slotGetGame(gameCode);
        await client.getGameState(gameCode, '');
    }

    /** 建立連線共用 Client 含mock */
    private async getClient(): Promise<SlotApiClient> {
        if (!this.slotApiClient) {
            const options = this.mockMode
                ? { httpBaseUrl: '', wsUrl: this.resolveWebSocketUrl() ?? undefined }
                : getSlotApiConnection();
            this.slotApiClient = this.createSlotApiClient(options);
        }

        if (!this.slotApiLoginPromise) {
            // 玩家端 API：token 由大廳給，不再自己登入，也先不連 WS（推播之後再接）；只有 mock 要連舊的 WS
            const connection = this.mockMode ? this.slotApiClient.connect('') : Promise.resolve();
            this.slotApiLoginPromise = connection.catch((error) => {
                this.slotApiLoginPromise = null;
                throw error;
            });
        }

        await this.slotApiLoginPromise;
        return this.slotApiClient;
    }

    /** 註冊所有 response 處理 */
    private createSlotApiClient(options: ConstructorParameters<typeof SlotApiClient>[0]): SlotApiClient {
        const client = new SlotApiClient(options);
        const gameStore = this.storeManager.getGameStore();
        client.registerHandler(new SlotSpinResponseHandler(gameStore, this));
        client.registerHandler(new GetGameInfoResponseHandler(gameStore));
        client.registerHandler(new GetGameStateResponseHandler(gameStore));
        client.registerHandler(new GetBetHistoryResponseHandler(gameStore, this));
        client.registerHandler(new GetBetDetailResponseHandler(this.cache.betDetails, gameStore));
        client.registerHandler(
            new JackpotPoolResponseHandler(SLOT_API_RESPONSE_TYPE.GET_JACKPOT_POOL_RESPONSE, gameStore)
        );
        client.registerHandler(
            new JackpotPoolResponseHandler(SLOT_API_RESPONSE_TYPE.SUBSCRIBE_JACKPOT_POOL_RESPONSE, gameStore)
        );
        client.registerHandler(new JackpotPoolResponseHandler(SLOT_API_RESPONSE_TYPE.JACKPOT_POOL_UPDATE, gameStore));
        return client;
    }

    /** 取得幣別 */
    private resolveCurrency(): string {
        if (typeof globalThis.location === 'undefined') return this.currency;
        // 原生的 URL 建構子在部分裝置上無法正確解析 location.href 會丟例外 讀不到網址列參數就當作沒有覆寫
        try {
            const params = new URL(globalThis.location.href).searchParams;
            return params.get('currency') ?? this.currency;
        } catch {
            return this.currency;
        }
    }

    /** 覆寫ws url */
    private resolveWebSocketUrl(): string | null {
        if (typeof globalThis.location === 'undefined') return null;
        try {
            const params = new URL(globalThis.location.href).searchParams;
            return params.get('ws_url') ?? params.get('wsUrl');
        } catch {
            return null;
        }
    }

    /**
     * 依 entry 的 language 切換語言：商戶原樣轉交、不驗證，這裡只認 en 與 zh-TW（對應現有的 zh-HK 繁體語系檔），
     * 空字串或其他值維持目前語言。
     */
    private async applyLanguage(language: string): Promise<void> {
        const mapped = language === 'en' ? 'en' : language === 'zh-TW' ? 'zh-HK' : '';
        if (mapped) await switchLanguage(mapped, GameConfigManager.GAMEID);
    }

    /** 處理錯誤 恢復狀態 */
    private handleError(error: any): void {
        // 文件規定要重打 entry 的情況，不彈錯誤：401（session 失效）；
        // 4017／4022（扣款中）與 4500（內部錯誤）同一個 prev_step_id 重送仍失敗（附錄 B，重送在 SlotApiClient.bet）
        if (error instanceof SlotApiHttpError && (error.kind === 'unauthorized'
            || error.code === SLOT_API_CODE.WRITE_PENDING
            || error.code === SLOT_API_CODE.ROUND_BUSY
            || error.code === SLOT_API_CODE.INTERNAL)) {
            void this.reenter();
            this.storeManager.getGameStore()?.setSpinStatus?.(GAMESTOREMAP.NEW_GAME);
            return;
        }
        // 餘額不足：沿用現有的儲值提示（儲值後同一個 prev_step_id 重送，下一次按轉就會用到它）
        if (error instanceof SlotApiHttpError && error.code === SLOT_API_CODE.INSUFFICIENT_BALANCE) {
            this.storeManager.getViewStore().showStoreAlertView('', getLocalizedString('1102'));
            this.storeManager.getGameStore()?.setSpinStatus?.(GAMESTOREMAP.NEW_GAME);
            return;
        }
        const code = error?.body?.code ?? error?.code ?? 'Error';
        const message = error?.body?.message ?? error?.errors?.[0] ?? error?.message ?? String(error);
        this.storeManager.getViewStore().showAlertView(String(code), String(message));
        this.storeManager.getGameStore()?.setSpinStatus?.(GAMESTOREMAP.NEW_GAME);
    }

    /**
     * 進場失敗時能不能改走 mock：只有開發版、且是「連不上」（網路失敗、5xx）才可以。
     * 後端有回應的錯誤（業務碼如 4014、4011、4023，或 401）是真實結果，不能切；程式、適配及請求參數錯誤也直接往外拋。
     */
    private canFallbackToMock(error: unknown): error is SlotApiHttpError {
        return !this.mockMode && error instanceof SlotApiHttpError && (error.kind === 'network' || error.kind === 'http') && autoFallbackToMock();
    }

    /**
     * 共用 mock 切換：無 token 或 API 請求失敗時使用；同時發生只建立一次連線。
     * 清除真實局游標及歷史快取，避免拿真實資料接續 mock。
     */
    private async fallbackToMock(error?: SlotApiHttpError): Promise<SlotApiClient> {
        if (this.mockSwitch) return this.mockSwitch;
        this.mockSwitch = (async () => {
            console.warn('[HttpClientStore] 切換為模擬模式', error ?? '未提供 token');
            this.close();
            this.mockMode = true;
            this.entry = null;
            this.betPlan = [];
            this.prevStepId = '';
            this.cache.betDetails.clear();
            this.setIsUpdate(true);
            await startGameMock();
            return this.getClient();
        })();
        return this.mockSwitch;
    }
}
