import { _decorator, Button, Color, Component, director, Label, Node, sp, Sprite, tween, Tween, UIOpacity, Vec3 } from 'cc';
import AppAudio, { StagedEffectPlayer } from '../audio/AppAudio';
import { EFFECTSMAP } from '../audio/AudioConfig';
import StoreManager from '../store/StoreManager';
import { GameViewAdapter } from './GameViewAdapter';
import GameConfigManager from '../config/GameConfigManager';
import { WinTier } from '../config/GameConst';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import { trySetAnimation } from '../utils/SpineSafe';

const { ccclass, property } = _decorator;

// 包住所有 spine 的內容子節點
const WIN_CONTENT_NODE_NAME = 'parent';

// 企劃 §9 報獎連貫順序：BIG → MEGA → SUPER → EPIC
const THRESHOLDS: { min: number; key: WinTier }[] = [
    { min: 51, key: WinTier.EPIC },
    { min: 50, key: WinTier.SUPER },
    { min: 20, key: WinTier.MEGA },
    { min: 10, key: WinTier.BIG },
    { min: 0, key: WinTier.WIN },
];

const WIN_LOOP_MAP: Partial<Record<WinTier, EFFECTSMAP>> = {
    [WinTier.BIG]: EFFECTSMAP.BIGWIN_LOOP,
    [WinTier.SUPER]: EFFECTSMAP.SUPERWIN_LOOP,
    [WinTier.MEGA]: EFFECTSMAP.MEGAWIN_LOOP,
    [WinTier.EPIC]: EFFECTSMAP.EPICWIN_LOOP,
};

const ESCALATE: WinTier[] = [WinTier.BIG, WinTier.MEGA, WinTier.SUPER, WinTier.EPIC];

// 各等級進場音效 依 ESCALATE 順序分階
const WIN_START_STAGES: EFFECTSMAP[] = [EFFECTSMAP.BIG_WIN_IN, EFFECTSMAP.MEGA_WIN_IN, EFFECTSMAP.SUPER_WIN_IN, EFFECTSMAP.EPIC_WIN_IN];
const ESCALATE_DWELL = 2.0;

// 小獎 spine 只有這兩支動畫 沒有 loop
const SMALL_WIN_BEGIN_ANIM = 'begin';
const SMALL_WIN_END_ANIM = 'end';

@ccclass('1001/WinAnimationView')
export class WinAnimationView extends Component {
    @property(sp.Skeleton)
    winSpine: sp.Skeleton = null!;

    @property(Label)
    winLabel: Label = null!;

    @property({ type: sp.Skeleton, tooltip: '小獎用的 spine（parent/win_s）' })
    smallWinSpine: sp.Skeleton | null = null;

    @property({ type: Label, tooltip: '小獎的跑分數字（parent/winLabel_s）' })
    smallWinLabel: Label | null = null;

    @property(Button)
    dismissBtn: Button = null!;

    private resolveClose: (() => void) | null = null;
    private dismissTimer: (() => void) | null = null;
    private dismissed: boolean = false;
    private currentKey: WinTier | '' = '';
    private finalKey: WinTier | '' = '';
    private currentLoopPath: string = '';
    private scoreLoopPlaying: boolean = false;
    private escalateTimers: (() => void)[] = [];
    public onDismissing: (() => void) | null = null;
    private winStartStages: StagedEffectPlayer | null = null;
    private disposeOrientation: (() => void) | null = null;
    private adapterDefaults = new Map<Node, { position: Vec3; scale: Vec3 }>();
    // 這次報獎走小獎那組
    private useSmallWin: boolean = false;

    public dismissExternal(): void {
        this.onDismiss();
    }

    protected override onLoad(): void {
        this.dismissBtn.node.on(Button.EventType.CLICK, this.onDismiss, this);
        this.applyAdapterOverride();
        this.winStartStages = new StagedEffectPlayer(GameConfigManager.GAMEID, WIN_START_STAGES);
        this.disposeOrientation = gameRuntimeEventBus.on(GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, () => {
            this.applyAdapterOverride();
        });
    }

    private applyAdapterOverride(): void {
        for (const [contentNode, defaults] of this.adapterDefaults) {
            if (!contentNode.isValid) continue;
            contentNode.setPosition(defaults.position);
            contentNode.setScale(defaults.scale);
        }
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return;
        const adapters = scene.getComponentsInChildren(GameViewAdapter);
        const adapter = adapters.find((a) => a.node.name === adapterName);
        if (!adapter) return;
        const contentNode = this.node.getChildByName(WIN_CONTENT_NODE_NAME);
        if (!contentNode) {
            console.warn(`[WinAnim] content node '${WIN_CONTENT_NODE_NAME}' not found`);
            return;
        }
        let defaults = this.adapterDefaults.get(contentNode);
        if (!defaults) {
            defaults = { position: contentNode.position.clone(), scale: contentNode.scale.clone() };
            this.adapterDefaults.set(contentNode, defaults);
        }
        contentNode.setPosition(defaults.position);
        contentNode.setScale(defaults.scale);
        const lp = adapter.winAnimationContentLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) contentNode.setPosition(lp);
        const sc = adapter.winAnimationContentScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) contentNode.setScale(sc);
    }

    protected override onDestroy(): void {
        this.disposeOrientation?.();
        this.disposeOrientation = null;
        if (this.currentLoopPath) {
            AppAudio.getInstance().stopLoopEffect(this.currentLoopPath);
            this.currentLoopPath = '';
        }
        this.stopScoreLoop();
        if (this.dismissTimer) {
            this.unschedule(this.dismissTimer);
            this.dismissTimer = null;
        }
        this.scoreRunning = false;
        this.clearEscalateTimers();
        Tween.stopAllByTarget(this.node);
    }

    static getWinKey(totalWin: number, bet: number): WinTier | null {
        const multiplier = bet > 0 ? totalWin / bet : 0;
        for (const t of THRESHOLDS) {
            if (multiplier >= t.min) return t.key;
        }
        return null;
    }

    show(totalWin: number, bet: number, forceKey?: WinTier): Promise<void> {
        const key = forceKey ?? WinAnimationView.getWinKey(totalWin, bet);
        if (!key) return Promise.resolve();

        this.applyAdapterOverride();

        return new Promise((resolve) => {
            this.resolveClose = resolve;
            this.dismissed = false;
            this.scoreFinished = false;
            this.waitingDismiss = false;
            this.currentKey = '';
            this.finalKey = key;
            this.winStartStages?.reset();
            this.node.active = true;

            const isEscalate = key !== WinTier.WIN && key !== WinTier.TOTAL;
            if (key === WinTier.TOTAL) AppAudio.getInstance().playEffect(EFFECTSMAP.TOTAL_WIN);
            // 一般小獎(WinTier.WIN)不 fade 背景音樂 其他等級才要
            if (key !== WinTier.WIN) this.fadeBgm(0, 0.5);
            if (key === WinTier.WIN) this.hideBlackBg();
            else this.fadeBlackBg(153, 0.333);

            this.useSmallWin = key === WinTier.WIN && this.isSmallWinReady();
            this.showWinNodes(this.useSmallWin);
            const label = this.activeLabel();
            label.string = '';

            const targetIdx = ESCALATE.indexOf(key);
            if (this.useSmallWin) this.playSmallWinBegin();
            else this.playTier(isEscalate ? WinTier.BIG : key);
            this.playLabelBirth(label);

            const multiplier = bet > 0 ? totalWin / bet : 0;
            let scoreDuration: number;
            this.clearEscalateTimers();
            if (key === WinTier.TOTAL) {
                scoreDuration = 0;
            } else if (isEscalate) {
                scoreDuration = (targetIdx + 1) * ESCALATE_DWELL;
                for (let i = 1; i <= targetIdx; i++) {
                    const tk = ESCALATE[i];
                    const cb = () => this.playTier(tk);
                    this.escalateTimers.push(cb);
                    this.scheduleOnce(cb, i * ESCALATE_DWELL);
                }
            } else {
                scoreDuration = Math.min(multiplier / 2, 15);
            }
            this.runScore(totalWin, scoreDuration, label).then(() => {
                if (this.scoreFinished) return;
                this.scoreFinished = true;
                this.stopLoopAndPlayEnd();
                this.startWaitingDismiss();
            });
        });
    }

    dismiss(): void {
        this.onDismiss();
    }

    private scoreFinished: boolean = false;
    private waitingDismiss: boolean = false;

    private _notifying: boolean = false;
    private onDismiss(): void {
        if (this.dismissed) return;
        if (!this._notifying) {
            this._notifying = true;
            try {
                this.onDismissing?.();
            } finally {
                this._notifying = false;
            }
        }

        if (!this.scoreFinished) {
            this.scoreFinished = true;
            this.clearEscalateTimers();
            // skip 時直接切到最終
            if (this.finalKey && this.currentKey !== this.finalKey) {
                this.currentKey = this.finalKey;
                try {
                    this.winSpine.setAnimation(0, `${this.finalKey}_loop`, true);
                } catch (e) {}
            }
            this.stopScore();
            this.stopLoopAndPlayEnd(EFFECTSMAP.WIN_SKIP);
            this.startWaitingDismiss();
            return;
        }

        if (this.waitingDismiss) {
            this.waitingDismiss = false;
            if (this.dismissTimer) {
                this.unschedule(this.dismissTimer);
                this.dismissTimer = null;
            }
            this.playOff();
            return;
        }

        this.playOff();
    }

    private startWaitingDismiss(): void {
        this.waitingDismiss = true;
        if (this.dismissTimer) this.unschedule(this.dismissTimer);
        const cb = () => {
            this.dismissTimer = null;
            this.waitingDismiss = false;
            this.onDismiss();
        };
        this.dismissTimer = cb;
        this.scheduleOnce(cb, 2);
    }

    private fadeBlackBg(target: number, duration: number): void {
        const node = this.dismissBtn?.node;
        if (!node) return;
        const sprite = node.getComponent(Sprite);
        if (sprite) sprite.color = new Color(0, 0, 0, 255);
        const uo = node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
        if (target > 0) uo.opacity = 0;
        Tween.stopAllByTarget(uo);
        tween(uo).to(duration, { opacity: target }).start();
    }

    private hideBlackBg(): void {
        const node = this.dismissBtn?.node;
        if (!node) return;
        const uo = node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
        Tween.stopAllByTarget(uo);
        uo.opacity = 0;
    }

    private playOff(): void {
        if (this.dismissed) return;
        this.dismissed = true;
        this.fadeBlackBg(0, 0.333);
        if (this.dismissTimer) {
            this.unschedule(this.dismissTimer);
            this.dismissTimer = null;
        }

        const label = this.activeLabel();
        if (label.node.active) this.playLabelOff(label);

        const spine = this.activeSpine();
        if (!spine.node.active || !this.currentKey) {
            this.close();
            return;
        }

        const safetyCb = () => this.close();
        this.scheduleOnce(safetyCb, 1);
        try {
            spine.setAnimation(0, this.useSmallWin ? SMALL_WIN_END_ANIM : `${this.currentKey}_end`, false);
            spine.setCompleteListener(() => {
                this.unschedule(safetyCb);
                spine.setCompleteListener(null!);
                this.close();
            });
        } catch (e) {
            this.unschedule(safetyCb);
            this.close();
        }
    }

    /**
     * 小獎的 spine 與數字有沒有接好 沒接好就改走大獎 spine
     *
     * @returns 兩格都接上且節點有效為 true
     */
    private isSmallWinReady(): boolean {
        return !!(this.smallWinSpine?.isValid && this.smallWinLabel?.isValid);
    }

    /**
     * 只打開這次要用的那組 spine 與數字
     *
     * @param small true 用小獎那組 false 用大獎那組
     */
    private showWinNodes(small: boolean): void {
        this.winSpine.node.active = !small;
        this.winLabel.node.active = !small;
        if (this.smallWinSpine) this.smallWinSpine.node.active = small;
        if (this.smallWinLabel) this.smallWinLabel.node.active = small;
    }

    /** 這次報獎在用的 spine */
    private activeSpine(): sp.Skeleton {
        return this.useSmallWin && this.smallWinSpine ? this.smallWinSpine : this.winSpine;
    }

    /** 這次報獎在用的跑分數字 */
    private activeLabel(): Label {
        return this.useSmallWin && this.smallWinLabel ? this.smallWinLabel : this.winLabel;
    }

    /** 小獎進場 播一次 begin 後停在最後一格 */
    private playSmallWinBegin(): void {
        this.currentKey = WinTier.WIN;
        const spine = this.smallWinSpine!;
        spine.setCompleteListener(null!);
        trySetAnimation(spine, SMALL_WIN_BEGIN_ANIM, false, 'WinAnimationView.playSmallWinBegin');
    }

    private close(): void {
        this.stopLoopAndPlayEnd();
        this.fadeBgm(1, 0.5, () => {
            if (this.node?.isValid) this.node.active = false;
            const resolve = this.resolveClose;
            this.resolveClose = null;
            resolve?.();
        });
    }

    private stopLoopAndPlayEnd(endPath: string = EFFECTSMAP.WIN_END): void {
        if (this.currentLoopPath) {
            AppAudio.getInstance().stopLoopEffect(this.currentLoopPath, endPath);
            this.currentLoopPath = '';
        }
    }

    private clearEscalateTimers(): void {
        for (const cb of this.escalateTimers) this.unschedule(cb);
        this.escalateTimers = [];
    }

    private playTier(key: WinTier): void {
        this.currentKey = key;
        if (ESCALATE.includes(key)) this.winStartStages?.next();
        const loopPath = WIN_LOOP_MAP[key];
        if (loopPath && loopPath !== this.currentLoopPath) {
            const prevLoopPath = this.currentLoopPath;
            this.currentLoopPath = loopPath;
            if (prevLoopPath) AppAudio.getInstance().stopLoopEffect(prevLoopPath);
            this.scheduleOnce(() => {
                if (this.currentLoopPath === loopPath) AppAudio.getInstance().playLoopEffect(loopPath);
            }, 0.5);
        }
        try {
            this.winSpine.setAnimation(0, `${key}_begin`, false);
            this.winSpine.setCompleteListener(() => {
                this.winSpine.setCompleteListener(null!);
                if (this.currentKey === key && this.winSpine.node?.isValid) {
                    this.winSpine.setAnimation(0, `${key}_loop`, true);
                }
            });
        } catch (e) {}
    }

    private scoreTargetWin: number = 0;
    private scoreLabel: Label | null = null;
    private scoreDuration: number = 0;
    private scoreElapsed: number = 0;
    private scoreRunning: boolean = false;
    private scoreResolve: (() => void) | null = null;

    // 用 dt 累加 不用固定間隔 setTimeout 累加寫法能吃到 director hook 的加速縮放
    protected override update(dt: number): void {
        if (!this.scoreRunning) return;
        this.scoreElapsed += dt;
        const ratio = this.scoreDuration <= 0 ? 1 : Math.min(this.scoreElapsed / this.scoreDuration, 1);
        const cur = this.scoreTargetWin * ratio;
        if (this.scoreLabel) this.scoreLabel.string = StoreManager.getInstance().getGameStore().formatAmount(cur);
        if (ratio >= 1) {
            this.scoreRunning = false;
            this.stopScoreLoop();
            const resolve = this.scoreResolve;
            this.scoreResolve = null;
            resolve?.();
        }
    }

    private runScore(totalWin: number, duration: number, label: Label): Promise<void> {
        this.stopScore();
        this.scoreTargetWin = totalWin;
        this.scoreLabel = label;
        this.scoreDuration = duration;
        this.scoreElapsed = 0;

        return new Promise<void>((resolve) => {
            if (duration <= 0) {
                label.string = StoreManager.getInstance().getGameStore().formatAmount(totalWin);
                resolve();
                return;
            }
            this.scoreResolve = resolve;
            this.scoreRunning = true;
            this.scoreLoopPlaying = true;
            AppAudio.getInstance().playLoopEffect(EFFECTSMAP.WIN_LOOP);
        });
    }

    private stopScore(): void {
        if (this.scoreRunning) {
            this.scoreRunning = false;
            this.stopScoreLoop();
            this.scoreResolve = null;
            if (this.scoreLabel) {
                this.scoreLabel.string = StoreManager.getInstance().getGameStore().formatAmount(this.scoreTargetWin);
            }
        }
    }

    private stopScoreLoop(): void {
        if (!this.scoreLoopPlaying) return;
        this.scoreLoopPlaying = false;
        AppAudio.getInstance().stopLoopEffect(EFFECTSMAP.WIN_LOOP);
    }

    private playLabelBirth(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        node.setScale(0.3, 0.3, 1);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 0;
        tween(uiOpacity).to(0.333, { opacity: 255 }).start();

        tween(node)
            .to(0.333, { scale: new Vec3(1.15, 1.15, 1) }, { easing: 'backOut' })
            .to(0.167, { scale: new Vec3(1, 1, 1) })
            .start();
    }

    private playLabelOff(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
        tween(uiOpacity).delay(0.167).to(0.333, { opacity: 0 }).start();

        tween(node)
            .to(0.167, { scale: new Vec3(0.9, 0.9, 1) })
            .to(0.333, { scale: new Vec3(2, 2, 1) })
            .start();
    }

    private fadeBgm(target: number, duration: number, onComplete?: () => void): void {
        AppAudio.getInstance().fadeMusicVolume(target, duration, onComplete);
    }
}
