/**
 * 共用狀態 key 常數（比照舊專案 SceneMain/SGDefine 的 DF_GameState）。
 *
 * NG/FG 是目前 1001/1002 都有的兩個共用狀態；未來若有遊戲專屬的第三種狀態
 * （例如 Bonus/Buy-feature 轉場），不必硬塞進這個共用列舉，可在各遊戲自己的
 * State 檔案內用額外的字串 key（changeState() 本身吃 string，不限制只能是
 * GameStateKey 裡定義的值）。
 */
export const GameStateKey = {
    NG: 'NG',
    FG: 'FG',
    BG: 'BG',
} as const;

export type GameStateKey = (typeof GameStateKey)[keyof typeof GameStateKey];
